var n=`1359-sancocho-colombiano`;var t=`world-1359`;var a=`CO`;var s=`south-america`;var o=4;var r=157;var g={en:`Sancocho Colombiano`,ua:`Колумбійське санкочо`};var l={en:`Sancocho Colombiano is a dish from Colombia featuring beef shank, chicken thigh, yellow onion, plantain. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Колумбійське санкочо, страва кухні країни Колумбія з такими основними складниками: яловича гомілка, куряче стегно, жовта цибуля, плантан. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var h=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 110 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 110 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:110,i:[[`beef-shank`,620,`g`],[`chicken-thigh`,620,`g`],[`water`,2e3,`ml`],[`yellow-onion`,160,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 40 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 40 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:40,i:[[`plantain`,380,`g`],[`cassava-root`,380,`g`],[`potato`,360,`g`],[`sweet-corn`,2,`pcs`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,4,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,35,`g`],[`lime`,2,`pcs`]]}];var m={slug:n,id:t,country:`CO`,region:s,servings:4,minutes:157,title:g,text:l,steps:h};export{a as country,m as default,t as id,r as minutes,s as region,o as servings,n as slug,h as steps,l as text,g as title};